static const uint8_t kN = sizeof(kRoute) / sizeof(kRoute[0]);
// true bearing (clockwise from north) = kBearingOfRouteYaw0 - routeYaw. From the facade:
// GPS course along B = 125 deg at route yaw kRoute[0].ref (-37.8).
static const float kBearingOfRouteYaw0 = 125.0f + (-37.8f);
static const float kEffortEnd = 0.97f;   // EFFORT legs end here (teaching run zig-zagged a bit)
static const float kMPerDeg = 111194.93f;

uint8_t RouteFollow::count() { return kN; }
const RouteFollow::Leg& RouteFollow::leg(uint8_t i) { return kRoute[i < kN ? i : kN - 1]; }

static bool gpsGood(const Sensors& s) { return s.gpsFix() && s.hdop() > 0 && s.hdop() <= 2.5f; }
static void enu(double lat0, double lon0, double lat1, double lon1, float& e, float& n) {
  n = (float)((lat1 - lat0) * kMPerDeg);
  e = (float)((lon1 - lon0) * kMPerDeg * cos(lat0 * DEG_TO_RAD));
}

